// FEAL G function
uint8_t g_function(uint8_t a, uint8_t b, uint8_t x) {
    uint8_t temp = (a + b + x) & 0xFF;  // Keep it as 8-bit
    return ((temp << 2) | (temp >> 6)) & 0xFF;
}

// FEAL F function
uint32_t f_function(uint32_t input_val) {
    uint8_t x[4];
    uint8_t y[4];

    // Extract bytes from input (big-endian)
    for (int i = 0; i < 4; i++) {
